import React from 'react';
import './Projects.css';

const PROJECTS = [
  {
    title: 'ExploitXplorers',
    desc: 'Community-driven cybersecurity platform offering hands-on knowledge and awareness for students.',
    tags: ['MERN', 'Auth', 'Security'],
    bg: '#000000',
    light: false,
  },
  {
    title: 'Priscripto',
    desc: 'AI-driven healthcare appointment system optimizing patient-doctor scheduling and accessibility.',
    tags: ['Next.js', 'AI', 'MongoDB'],
    bg: '#4452FF',
    light: false,
  },
  {
    title: 'Hospital Booking',
    desc: 'Full-cycle medical management system for seamless appointment handling and patient records.',
    tags: ['React', 'Node.js', 'Express'],
    bg: '#f3f4f6',
    light: true,
  },
  {
    title: 'Blog System',
    desc: 'Dynamic content management space for creators to publish, manage, and share technical insights.',
    tags: ['React', 'Tailwind', 'Appwrite'],
    bg: '#111827',
    light: false,
  },
  {
    title: 'Portfolio v1',
    desc: 'Personal portfolio showcasing projects, skills, and achievements with a modern dark design.',
    tags: ['React', 'CSS', 'Vite'],
    bg: '#1e3a5f',
    light: false,
  },
];

const ProjectCard = ({ proj }) => (
  <div className="project-card group">
    <div className="project-card__thumb" style={{ backgroundColor: proj.bg }}>
      <span className={`project-card__initial ${proj.light ? 'text-black' : 'text-white'}`}>
        {proj.title[0]}
      </span>
    </div>
    <div className="project-card__body">
      <div className="project-card__top">
        <h3 className="project-card__title">{proj.title}</h3>
        <span className="project-card__arrow">→</span>
      </div>
      <p className="project-card__desc">{proj.desc}</p>
      <div className="project-card__tags">
        {proj.tags.map(t => (
          <span key={t} className="project-card__tag">{t}</span>
        ))}
      </div>
    </div>
  </div>
);

export default function Projects({ onNavigate }) {
  return (
    <section className="py-section" id="projects">
      <div className="container">
        <div className="projects-header">
          <div>
            <h2 className="font-display text-3xl font-semibold lg:text-4xl">Projects</h2>
            <p className="text-xl lg:text-2xl mt-2 text-gray-600">
              Real-world products built to solve problems and scale reliably.
            </p>
          </div>
          <button onClick={() => onNavigate('projects')} className="projects-all-btn">
            View All Projects <span>→</span>
          </button>
        </div>
      </div>

      {/* Marquee scroll */}
      <div className="projects-marquee-wrapper">
        <div className="projects-marquee">
          <div className="projects-marquee__track">
            {[...PROJECTS, ...PROJECTS].map((proj, i) => (
              <ProjectCard key={i} proj={proj} />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
